import subprocess
import yaml
from flask import Flask, request

app = Flask(__name__)

@app.route('/ping')
def ping():
    host = request.args.get('host', '')
    out = subprocess.check_output(f'ping -n 1 {host}', shell=True)
    return out

@app.route('/import', methods=['POST'])
def import_config():
    data = yaml.load(request.files['file'].read(), Loader=yaml.Loader)
    return {'keys': list(data.keys())}

